/*
@mmianji-beauty
@id: idic.pink-crystal-wheel
@name: 少女病 · 消息列表
@mode: hidden
@version: 4.1.0
*/
(function (root) {
  'use strict';
/* Adapted from ios_avatar_wheel_picker.html. Host owns its visual theme and data. */
class PinkWheel {
  constructor(container, list, items, { onChange, onOpen, onUserInteraction } = {}) {
    this.container = container;
    this.list = list;
    this.onChange = onChange || (() => {});
    this.onOpen = onOpen || (() => {});
    this.onUserInteraction = onUserInteraction || (() => {});
    this.itemHeight = 50;
    this.containerHeight = 280;
    this.centerOffset = (this.containerHeight - this.itemHeight) / 2;
    this.scrollY = 0;
    this.targetY = 0;
    this.velocity = 0;
    this.lastIndex = -1;
    this.animFrameId = null;
    this.wheelTimer = null;
    this.mode = 'IDLE';
    this.source = 'program';
    this.isDragging = false;
    this.pointerId = null;
    this.velocityHistory = [];
    this.springStiffness = 240;
    this.springDamping = 21;
    this.paused = false;
    this.destroyed = false;
    this.itemElements = [];
    this.visibleItems = new Set();
    this.handlers = {
      down: e => this.onPointerDown(e),
      move: e => this.onPointerMove(e),
      up: e => this.onPointerUp(e, false),
      cancel: e => this.onPointerUp(e, true),
      wheel: e => this.onWheel(e),
      key: e => this.onKeyDown(e),
      click: e => { e.preventDefault(); e.stopPropagation(); }
    };
    this.container.style.touchAction = 'none';
    this.container.style.maskImage = 'linear-gradient(to bottom, transparent 0%, black 16%, black 84%, transparent 100%)';
    this.container.style.webkitMaskImage = 'linear-gradient(to bottom, transparent 0%, black 16%, black 84%, transparent 100%)';
    this.bindEvents();
    this.setItems(items || []);
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.measure());
      this.resizeObserver.observe(this.container);
    }
    this.measure();
  }

  bindEvents() {
    this.container.addEventListener('pointerdown', this.handlers.down);
    window.addEventListener('pointermove', this.handlers.move, { passive: false });
    window.addEventListener('pointerup', this.handlers.up);
    window.addEventListener('pointercancel', this.handlers.cancel);
    this.container.addEventListener('wheel', this.handlers.wheel, { passive: false });
    this.list.addEventListener('keydown', this.handlers.key);
    // Pointer activation is handled on pointerup after measuring movement; suppress synthetic clicks.
    this.list.addEventListener('click', this.handlers.click);
  }

  measure() {
    if (this.destroyed) return;
    const height = this.container.clientHeight;
    if (height > 0) this.containerHeight = height;
    this.centerOffset = (this.containerHeight - this.itemHeight) / 2;
    this.render();
  }

  setItems(items) {
    const previous = this.items && this.items[this.lastIndex];
    const previousKey = previous && previous.key;
    this.stopMotion();
    this.releasePointer();
    this.isDragging = false;
    this.pointerId = null;
    this.items = Array.isArray(items) ? items.slice() : [];
    this.itemCount = this.items.length;
    this.maxScroll = Math.max(0, (this.itemCount - 1) * this.itemHeight);
    this.list.replaceChildren();
    this.visibleItems.clear();
    this.ariaIndex = -1;
    this.itemElements = this.items.map((item, index) => {
      const el = document.createElement('div');
      el.className = 'picker-item';
      el.style.visibility = 'hidden';
      el.dataset.index = String(index);
      el.setAttribute('role', 'button');
      el.setAttribute('aria-label', item.name || '会话');
      el.tabIndex = 0;
      const avatar = document.createElement('div');
      avatar.className = 'avatar-wrapper';
      if (item.avatar) {
        const img = document.createElement('img');
        img.src = item.avatar;
        img.alt = '';
        img.draggable = false;
        img.style.cssText = 'width:100%;height:100%;object-fit:cover;border-radius:50%;';
        avatar.appendChild(img);
      } else {
        const initial = document.createElement('span');
        initial.textContent = (item.name || '?').trim().slice(0, 1) || '?';
        avatar.appendChild(initial);
      }
      el.appendChild(avatar);
      this.list.appendChild(el);
      return el;
    });
    const preservedIndex = previousKey == null ? -1 : this.items.findIndex(item => item.key === previousKey);
    const nextIndex = this.itemCount ? Math.max(0, preservedIndex) : -1;
    this.lastIndex = -1;
    this.scrollY = this.targetY = Math.max(0, nextIndex) * this.itemHeight;
    this.source = 'data';
    this.render();
    if (nextIndex === -1) this.onChange(-1, -1, 'data');
  }

  stopMotion() {
    if (this.animFrameId != null) cancelAnimationFrame(this.animFrameId);
    if (this.wheelTimer != null) clearTimeout(this.wheelTimer);
    this.animFrameId = this.wheelTimer = null;
    this.velocity = 0;
    this.mode = 'IDLE';
  }

  releasePointer() {
    if (this.pointerId != null) {
      try { if (this.container.hasPointerCapture(this.pointerId)) this.container.releasePointerCapture(this.pointerId); } catch (_) {}
    }
  }

  onPointerDown(e) {
    if (this.paused || !this.itemCount || this.isDragging || (e.button !== undefined && e.button !== 0)) return;
    this.onUserInteraction('pointer');
    this.isDragging = true;
    this.pointerId = e.pointerId;
    this.mode = 'DRAGGING';
    this.source = 'pointer';
    this.startX = e.clientX;
    this.startY = e.clientY;
    this.maxPointerDistance = 0;
    this.pressedItem = e.target.closest('.picker-item');
    this.startScrollY = this.scrollY;
    this.lastTouchY = e.clientY;
    this.lastTouchTime = performance.now();
    this.velocityHistory = [];
    this.velocity = 0;
    if (this.animFrameId != null) cancelAnimationFrame(this.animFrameId);
    if (this.wheelTimer != null) clearTimeout(this.wheelTimer);
    this.animFrameId = this.wheelTimer = null;
    try { this.container.setPointerCapture(e.pointerId); } catch (_) {}
  }

  onPointerMove(e) {
    if (!this.isDragging || e.pointerId !== this.pointerId) return;
    if (e.cancelable) e.preventDefault();
    this.maxPointerDistance = Math.max(this.maxPointerDistance, Math.hypot(e.clientX - this.startX, e.clientY - this.startY));
    const currentY = e.clientY;
    const now = performance.now();
    const deltaY = this.startY - currentY;
    let nextScrollY = this.startScrollY + deltaY;
    if (nextScrollY < 0) nextScrollY = -this.rubberBand(-nextScrollY, this.containerHeight);
    else if (nextScrollY > this.maxScroll) nextScrollY = this.maxScroll + this.rubberBand(nextScrollY - this.maxScroll, this.containerHeight);
    const dt = now - this.lastTouchTime;
    if (dt > 0) {
      const instVel = (this.lastTouchY - currentY) / dt;
      this.velocityHistory.push({ vel: instVel, time: now });
      this.velocityHistory = this.velocityHistory.filter(v => now - v.time < 100);
    }
    this.lastTouchY = currentY;
    this.lastTouchTime = now;
    this.scrollY = nextScrollY;
    this.render();
  }

  onPointerUp(e, cancelled) {
    if (!this.isDragging || e.pointerId !== this.pointerId) return;
    this.isDragging = false;
    this.pointerId = null;
    try { if (this.container.hasPointerCapture(e.pointerId)) this.container.releasePointerCapture(e.pointerId); } catch (_) {}
    const distance = Math.max(this.maxPointerDistance, Math.hypot(e.clientX - this.startX, e.clientY - this.startY));
    const hit = document.elementFromPoint(e.clientX, e.clientY);
    const itemEl = hit && hit.closest('.picker-item');
    if (!cancelled && distance < 6 && itemEl && itemEl === this.pressedItem && this.list.contains(itemEl)) {
      const idx = Number(itemEl.dataset.index);
      if (idx === this.lastIndex) {
        this.snapToNearest();
        this.startPhysicsLoop();
        this.onOpen(idx, this.items[idx]);
      } else {
        this.scrollToIndex(idx, true, 'pointer');
      }
      this.pressedItem = null;
      return;
    }
    this.pressedItem = null;
    if (!cancelled && this.velocityHistory.length > 0) {
      const sum = this.velocityHistory.reduce((acc, v) => acc + v.vel, 0);
      this.velocity = (sum / this.velocityHistory.length) * 16.6;
    } else this.velocity = 0;
    if (Math.abs(this.velocity) > 1.2) this.mode = 'INERTIA';
    else this.snapToNearest();
    this.startPhysicsLoop();
  }

  onWheel(e) {
    if (this.paused || !this.itemCount) return;
    e.preventDefault();
    this.onUserInteraction('wheel');
    this.source = 'wheel';
    const delta = e.deltaY;
    let nextScrollY = this.scrollY + delta * 0.45;
    if (nextScrollY < -this.itemHeight * 0.5) nextScrollY = -this.itemHeight * 0.5;
    if (nextScrollY > this.maxScroll + this.itemHeight * 0.5) nextScrollY = this.maxScroll + this.itemHeight * 0.5;
    this.scrollY = nextScrollY;
    this.velocity = delta * 0.1;
    if (this.animFrameId != null) cancelAnimationFrame(this.animFrameId);
    this.animFrameId = null;
    if (this.wheelTimer != null) clearTimeout(this.wheelTimer);
    this.wheelTimer = setTimeout(() => {
      this.wheelTimer = null;
      this.snapToNearest();
      this.startPhysicsLoop();
    }, 110);
    this.render();
  }

  onKeyDown(e) {
    if (this.paused || !this.itemCount || !['Enter', ' ', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    const itemEl = e.target.closest('.picker-item');
    if (!itemEl) return;
    e.preventDefault();
    e.stopPropagation();
    this.onUserInteraction('keyboard');
    const idx = Number(itemEl.dataset.index);
    if (e.key === 'Enter' || e.key === ' ') {
      if (idx === this.lastIndex) this.onOpen(idx, this.items[idx]);
      else this.scrollToIndex(idx, true, 'keyboard');
    } else {
      const next = Math.max(0, Math.min(this.itemCount - 1, this.lastIndex + (e.key === 'ArrowUp' ? -1 : 1)));
      this.scrollToIndex(next, true, 'keyboard');
      this.itemElements[next].focus();
    }
  }

  rubberBand(distance, dimension) {
    return (1.0 - (1.0 / ((distance * 0.38 / dimension) + 1.0))) * dimension;
  }

  snapToNearest() {
    if (!this.itemCount) { this.mode = 'IDLE'; return; }
    const targetIndex = Math.max(0, Math.min(this.itemCount - 1, Math.round(this.scrollY / this.itemHeight)));
    this.targetY = targetIndex * this.itemHeight;
    this.mode = 'SPRING';
  }

  scrollToIndex(index, animate = true, source = 'program') {
    if (!this.itemCount || this.destroyed) return;
    const targetIndex = Math.max(0, Math.min(this.itemCount - 1, index));
    this.targetY = targetIndex * this.itemHeight;
    this.source = source;
    if (animate) {
      this.mode = 'SPRING';
      this.startPhysicsLoop();
    } else {
      this.stopMotion();
      this.scrollY = this.targetY;
      this.render();
    }
  }

  startPhysicsLoop() {
    if (this.paused || this.destroyed || !this.itemCount) return;
    if (this.animFrameId != null) cancelAnimationFrame(this.animFrameId);
    let lastTimestamp = performance.now();
    const step = now => {
      if (this.paused || this.destroyed) { this.animFrameId = null; return; }
      const dt = Math.min((now - lastTimestamp) / 1000, 0.032);
      lastTimestamp = now;
      if (this.mode === 'INERTIA') {
        this.scrollY += this.velocity;
        this.velocity *= 0.945;
        if (this.scrollY < 0 || this.scrollY > this.maxScroll) this.velocity *= 0.55;
        if (Math.abs(this.velocity) < 0.35) this.snapToNearest();
      } else if (this.mode === 'SPRING') {
        const displacement = this.scrollY - this.targetY;
        const springForce = -this.springStiffness * displacement;
        const dampingForce = -this.springDamping * this.velocity;
        const accel = springForce + dampingForce;
        this.velocity += accel * dt;
        this.scrollY += this.velocity * dt;
        if (Math.abs(displacement) < 0.2 && Math.abs(this.velocity) < 0.2) {
          this.scrollY = this.targetY;
          this.velocity = 0;
          this.mode = 'IDLE';
          this.animFrameId = null;
          this.render();
          return;
        }
      }
      this.render();
      this.animFrameId = this.mode !== 'IDLE' ? requestAnimationFrame(step) : null;
    };
    this.animFrameId = requestAnimationFrame(step);
  }

  render() {
    if (!this.itemCount || this.destroyed) return;
    const activeFloatIndex = this.scrollY / this.itemHeight;
    const currentRoundedIndex = Math.max(0, Math.min(this.itemCount - 1, Math.round(activeFloatIndex)));
    if (currentRoundedIndex !== this.lastIndex) {
      const previousIndex = this.lastIndex;
      this.lastIndex = currentRoundedIndex;
      this.onChange(currentRoundedIndex, previousIndex, this.source);
    }
    // Only project items that can intersect the masked wheel viewport.
    // Distant rows remain in the accessible DOM, but do not receive frame-by-frame style writes.
    const radius = Math.ceil(this.containerHeight / (2 * this.itemHeight)) + 3;
    const from = Math.max(0, Math.floor(activeFloatIndex) - radius);
    const to = Math.min(this.itemCount - 1, Math.ceil(activeFloatIndex) + radius);
    const nextVisible = new Set();
    for (let i = from; i <= to; i++) nextVisible.add(i);
    this.visibleItems.forEach(i => {
      if (!nextVisible.has(i)) this.itemElements[i].style.visibility = 'hidden';
    });
    for (let i = from; i <= to; i++) {
      const itemEl = this.itemElements[i];
      if (!this.visibleItems.has(i)) itemEl.style.visibility = '';
      const distFromCenter = i - activeFloatIndex;
      const absDist = Math.abs(distFromCenter);
      const posY = this.centerOffset + distFromCenter * this.itemHeight;
      const rotateX = -distFromCenter * 20;
      const scale = Math.max(0.62, 1.0 - absDist * 0.17);
      const opacity = Math.max(0.25, 1.0 - Math.pow(absDist / 2.6, 1.8));
      const translateZ = -Math.pow(absDist, 1.2) * 18;
      itemEl.style.transform = `translate3d(0px, ${posY}px, ${translateZ}px) rotateX(${rotateX}deg) scale(${scale})`;
      itemEl.style.opacity = opacity.toFixed(3);
      itemEl.classList.toggle('is-centered', absDist < 0.45);
    }
    if (this.ariaIndex !== currentRoundedIndex) {
      if (this.ariaIndex >= 0 && this.itemElements[this.ariaIndex]) this.itemElements[this.ariaIndex].setAttribute('aria-current', 'false');
      this.itemElements[currentRoundedIndex].setAttribute('aria-current', 'true');
      this.ariaIndex = currentRoundedIndex;
    }
    this.visibleItems = nextVisible;
  }

  pause() {
    if (this.paused || this.destroyed) return;
    this.paused = true;
    if (this.animFrameId != null) cancelAnimationFrame(this.animFrameId);
    if (this.wheelTimer != null) clearTimeout(this.wheelTimer);
    this.animFrameId = this.wheelTimer = null;
    this.releasePointer();
    this.isDragging = false;
    this.pointerId = null;
    if (this.itemCount) { this.velocity = 0; this.snapToNearest(); }
  }

  resume() {
    if (!this.paused || this.destroyed) return;
    this.paused = false;
    this.measure();
    if (this.mode !== 'IDLE') this.startPhysicsLoop();
  }

  destroy() {
    if (this.destroyed) return;
    this.stopMotion();
    this.releasePointer();
    this.destroyed = true;
    this.isDragging = false;
    if (this.resizeObserver) this.resizeObserver.disconnect();
    this.container.removeEventListener('pointerdown', this.handlers.down);
    window.removeEventListener('pointermove', this.handlers.move);
    window.removeEventListener('pointerup', this.handlers.up);
    window.removeEventListener('pointercancel', this.handlers.cancel);
    this.container.removeEventListener('wheel', this.handlers.wheel);
    this.list.removeEventListener('keydown', this.handlers.key);
    this.list.removeEventListener('click', this.handlers.click);
    this.list.replaceChildren();
  }
}

/* Read the host's rendered rows; the host remains the owner of chat data and navigation. */
function createHostBridge(onRowsChanged) {
  if (typeof onRowsChanged !== 'function') throw new TypeError('onRowsChanged must be a function');

  var container = null;
  var destroyed = false;
  var pending = null;
  var rowObserver = new MutationObserver(schedule);
  var documentObserver = new MutationObserver(function () {
    if (destroyed) return;
    var next = document.getElementById('chat-list-container');
    if (next !== container) bindContainer(next);
  });

  function textOf(element, selector) {
    var node = element.querySelector(selector);
    return node ? (node.textContent || '').trim() : '';
  }

  function rowKey(element) {
    var data = element.dataset;
    var type = data.groupId != null ? 'group' : 'contact';
    var id = type === 'group' ? data.groupId : data.contactId;
    if (id == null || id === '') return '';
    return [type, id, data.foundMessageId || '', data.searchSourceMode || '',
      data.searchStoryId || '', data.searchMessageIndex || ''].map(function (part) {
      return encodeURIComponent(String(part));
    }).join(':');
  }

  function readRows() {
    if (!container || !container.isConnected) return [];
    var duplicates = Object.create(null);
    return Array.prototype.reduce.call(container.children, function (rows, element) {
      if (!element.classList.contains('chat-list-item')) return rows;
      var base = rowKey(element);
      if (!base) return rows;
      var count = duplicates[base] || 0;
      duplicates[base] = count + 1;
      var img = element.querySelector('.avatar-container .avatar');
      var row = {
        key: count ? base + ':duplicate:' + count : base,
        name: textOf(element, '.chat-list-item-name'),
        avatar: img ? (img.src || img.currentSrc || '') : '',
        summary: textOf(element, '.chat-list-item-msg'),
        time: textOf(element, '.chat-list-item-time'),
        unread: textOf(element, '.unread-badge'),
        element: element
      };
      row.open = function () { return open(row); };
      rows.push(row);
      return rows;
    }, []);
  }

  function open(row) {
    var element = row && row.element;
    if (destroyed || !container || !element || !element.isConnected ||
        element.parentElement !== container || !rowKey(element)) return false;
    element.click();
    return true;
  }

  function flush() {
    pending = null;
    if (!destroyed) onRowsChanged(readRows());
  }

  function schedule() {
    if (destroyed || pending !== null) return;
    pending = setTimeout(flush, 32);
  }

  function bindContainer(next) {
    rowObserver.disconnect();
    container = next;
    if (container) {
      rowObserver.observe(container, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true,
        attributeFilter: ['src', 'class', 'data-contact-id', 'data-group-id',
          'data-found-message-id', 'data-search-source-mode', 'data-search-story-id',
          'data-search-message-index']
      });
    }
    schedule();
  }

  function destroy() {
    if (destroyed) return;
    destroyed = true;
    rowObserver.disconnect();
    documentObserver.disconnect();
    if (pending !== null) clearTimeout(pending);
    pending = null;
    container = null;
  }

  documentObserver.observe(document.documentElement, { childList: true, subtree: true });
  bindContainer(document.getElementById('chat-list-container'));
  return { getRows: readRows, open: open, refresh: schedule, destroy: destroy };
}


