#chat-list-view.pink-flip-active #chat-list-container {
  display: none !important;
}
#chat-list-view .pink-flip-stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  overflow: hidden;
  isolation: isolate;
  background: radial-gradient(ellipse at 64% 48%, #261e26 0%, #1B1B1F 40%, #161618 76%, #131315 100%);
}
#chat-list-view .pink-flip-frame {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: calc(100% - 74px);
  height: 100%;
  transition: width 480ms cubic-bezier(.2, .8, .25, 1);
  border: 0;
  display: block;
  background: transparent;
}
#chat-list-view .pink-wheel {
  position: absolute;
  z-index: 5;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 62px;
  height: min(280px, 58%);
  min-height: 220px;
  overflow: hidden;
  border: 1px solid rgba(220, 188, 204, .22);
  border-radius: 34px;
  background: linear-gradient(168deg, rgba(40, 31, 44, .76), rgba(21, 17, 24, .88));
  box-shadow: inset 0 1px 0 rgba(245, 226, 234, .12), inset 0 -1px 0 rgba(207, 160, 176, .1), 0 10px 26px rgba(7, 5, 10, .52);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  perspective: 650px;
  touch-action: none;
  user-select: none;
}
#chat-list-view .pink-wheel::before,
#chat-list-view .pink-wheel::after {
  content: '';
  display: block;
  position: absolute;
  left: 50%;
  width: 20px;
  height: 4px;
  transform: translateX(-50%);
  border-radius: 99px;
  background: linear-gradient(90deg, transparent, rgba(224, 194, 208, .38), transparent);
  pointer-events: none;
  z-index: 3;
}
#chat-list-view .pink-wheel::before { top: 9px; }
#chat-list-view .pink-wheel::after { bottom: 9px; }
#chat-list-view .pink-wheel-list {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 22%, #000 78%, transparent 100%);
  mask-image: linear-gradient(to bottom, transparent 0%, #000 22%, #000 78%, transparent 100%);
}
#chat-list-view .pink-wheel .picker-item {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 50px;
  display: flex;
  justify-content: center;
  align-items: center;
  transform-style: preserve-3d;
  cursor: pointer;
  will-change: transform, opacity;
}
#chat-list-view .pink-wheel .avatar-wrapper {
  width: 40px;
  height: 40px;
  border: 1px solid rgba(207, 160, 176, .52);
  border-radius: 50%;
  overflow: hidden;
  background: #271f2b;
  box-shadow: 0 0 0 2px #1c1620;
}
#chat-list-view .pink-wheel .avatar-wrapper img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
#chat-list-view .pink-wheel .picker-item.is-centered .avatar-wrapper {
  border-color: #edd7e2;
  box-shadow: 0 0 0 2px #b68096, 0 0 11px rgba(209, 152, 174, .34);
}
#chat-list-view .pink-wheel-empty {
  position: absolute;
  z-index: 7;
  left: 10px;
  top: 50%;
  width: 62px;
  transform: translateY(-50%);
  color: #cbb1bf;
  font-size: 11px;
  text-align: center;
  pointer-events: none;
}
@media (min-width: 700px) {
  #chat-list-view .pink-flip-stage { max-width: 620px; margin: 0 auto; }
}
#chat-list-view .pink-flip-stage.pink-phone-focus .pink-flip-frame {
  right: 0;
  width: 100%;
  transition-delay: 400ms;
}
#chat-list-view .pink-flip-stage.pink-phone-focus .pink-wheel:not(.pink-wheel-exit),
#chat-list-view .pink-flip-stage.pink-phone-focus .pink-wheel-empty:not(.pink-wheel-exit) {
  display: none !important;
}
#chat-list-view .pink-wheel.pink-wheel-exit { pointer-events: none; }
@keyframes pink-wheel-return {
  0% { opacity: 0; transform: translate(-18px, -50%); }
  65% { opacity: 1; transform: translate(-1px, -50%); }
  82% { opacity: 1; transform: translate(-3px, -50%); }
  100% { opacity: 1; transform: translate(0, -50%); }
}
#chat-list-view .pink-wheel.pink-wheel-enter,
#chat-list-view .pink-wheel-empty.pink-wheel-enter {
  animation: pink-wheel-return 480ms cubic-bezier(.2, .8, .25, 1) both;
}
#chat-list-view .pink-wheel.pink-wheel-exit,
#chat-list-view .pink-wheel-empty.pink-wheel-exit {
  animation: pink-wheel-return 480ms cubic-bezier(.2, .8, .25, 1) reverse both;
}
@media (prefers-reduced-motion: reduce) {
  #chat-list-view .pink-flip-frame { transition: none; }
  #chat-list-view .pink-wheel.pink-wheel-enter,
  #chat-list-view .pink-wheel-empty.pink-wheel-enter,
  #chat-list-view .pink-wheel.pink-wheel-exit,
  #chat-list-view .pink-wheel-empty.pink-wheel-exit { animation: none; }
}

/* Center the full-width phone toolbar while retaining the wheel and handset layout. */
#chat-list-view .pink-flip-stage .pink-flip-frame { width:100%; }

