  min-height: 36px !important;
  margin: 0 6px 0 0 !important;
  background: transparent !important;
  color: #EAE9E5 !important;
  border: 0 !important;
  border-radius: 18px !important;
  font-size: 13.5px !important;
  font-weight: 600 !important;
  letter-spacing: .08em !important;
  box-shadow: none !important;
}
/* 自信闪耀的 #E06389 粉晶糖果镀铬发送键 + 丘比特心箭 */
#chat-window-view #send-button {
  position: relative !important;
  flex: 0 0 38px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 38px !important;
  min-width: 38px !important;
  height: 38px !important;
  min-height: 38px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: linear-gradient(145deg, #F694B6 0%, #E06389 56%, #C2436B 100%) !important;
  background-image: linear-gradient(145deg, #F694B6 0%, #E06389 56%, #C2436B 100%) !important;
  color: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
  border: 1px solid rgba(255, 255, 255, .58) !important;
  border-radius: 50% !important;
  box-shadow:
    inset 0 1.5px 0 rgba(255, 255, 255, .62),
    0 0 16px rgba(224, 99, 137, .46),
    0 4px 10px rgba(0, 0, 0, .48) !important;
  transition: transform .16s ease, filter .18s ease, box-shadow .18s ease;
}
#chat-window-view #send-button .send-label {
  display: none !important;
}
#chat-window-view #send-button > .pcc-ico-wrap {
  transition: transform .32s cubic-bezier(.3, 1.5, .4, 1);
}
#chat-window-view #send-button:active,
#chat-window-view #send-button.send-pulse {
  transform: scale(.9);
  filter: brightness(1.08);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 0 0 5px rgba(224, 99, 137, .3), 0 0 22px rgba(224, 99, 137, .55) !important;
}
#chat-window-view #send-button:active > .pcc-ico-wrap,
#chat-window-view #send-button.send-pulse > .pcc-ico-wrap {
  transform: translate(2px, -2px) scale(1.08);
  transition-duration: .12s;
}
#chat-window-view #send-button:focus-visible {
  outline: 1.5px solid #EAE9E5 !important;
  outline-offset: 2px !important;
}

/* 点击发送飘起的粉晶爱心闪星（JS 动态生成并自动销毁） */
body > .pcc-send-spark {
  position: fixed !important;
  width: 24px !important;
  height: 24px !important;
  pointer-events: none !important;
  z-index: 9999 !important;
  filter: drop-shadow(0 0 8px rgba(224, 99, 137, .65)) !important;
  animation: pccSendSparkFloat 0.68s cubic-bezier(.2, .85, .25, 1) forwards !important;
}
body > .pcc-send-spark > svg {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
}
@keyframes pccSendSparkFloat {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.5) rotate(0deg); }
  22% { opacity: 1; transform: translate(-50%, -14px) scale(1.12) rotate(18deg); }
  65% { opacity: .88; transform: translate(-50%, -34px) scale(.94) rotate(42deg); }
  100% { opacity: 0; transform: translate(-50%, -46px) scale(.55) rotate(68deg); }
}

