/* ---------- 自绘主题 24px 珠宝级 SVG 图标系统（蕾丝 / 切面宝石 / 少女心 / 银锁链） ---------- */
body.pcc-chat-visible #chat-window-view .pcc-iconized > svg:not(.pcc-ico),
