}
body.pcc-chat-visible #chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-content > .quoted-message-display .sender-name::after { content: none !important; }
body.pcc-chat-visible #chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-content > .quoted-message-display .message-snippet {
