/* Reuse the V7 hero butterfly asset, keeping the original right-side lettering. */
body.pcc-chat-visible #chat-window-view .pcc-backdrop .pcc-bg-bf-echo { display:none!important; }
body.pcc-chat-visible #chat-window-view .pcc-backdrop .pcc-bg-bf-hero { display:block!important; left:50%!important; right:auto!important; top:calc(50% - 14px)!important; bottom:auto!important; width:min(64vw,250px)!important; height:auto!important; transform:translate(-50%,-50%)!important; animation:none!important; opacity:.4!important; filter:none!important; pointer-events:none!important; }
body.pcc-chat-visible #chat-window-view .pcc-backdrop-svg * { visibility:hidden; }
body.pcc-chat-visible #chat-window-view .pcc-backdrop-svg .pcc-zine-code { visibility:visible; }

#chat-window-view .bijou-drawer{position:absolute;z-index:80;left:0;right:0;top:var(--bijou-top,64px);height:calc(100% - var(--bijou-top,64px));display:flex;flex-direction:column;align-items:center;background:transparent;transform:translateY(calc(-100% - var(--bijou-top,64px)));opacity:0;visibility:hidden;pointer-events:none!important;transition:transform 420ms cubic-bezier(.2,.75,.2,1),opacity 260ms ease,visibility 0s linear 420ms;overflow:visible}
#chat-window-view .bijou-drawer.bijou-open{transform:translateY(0);opacity:1;visibility:visible;transition:transform 420ms cubic-bezier(.2,.75,.2,1),opacity 260ms ease,visibility 0s}
#chat-window-view .bijou-drawer-handle{position:relative;flex:0 0 25px;width:126px;display:flex;align-items:center;justify-content:center;gap:6px;color:#f9e4ee;background:#342338ed;border:1px solid #ad7592;border-radius:0 0 12px 12px;font:10px system-ui,sans-serif;touch-action:none;user-select:none;pointer-events:auto}
#chat-window-view .bijou-drawer-grip{display:block;width:25px;height:3px;border-radius:4px;background:#dca7bd}
#chat-window-view .bijou-drawer-handle button{width:22px;height:21px;padding:0;border:0;background:transparent;color:#ffe8f2;font-size:19px;line-height:1}
#chat-window-view .bijou-clip-defs{position:absolute;width:0;height:0;overflow:hidden;pointer-events:none}
#chat-window-view .bijou-frame{display:block;flex:none;width:100%;height:min(530px,calc(100% - 25px));border:0;background:transparent;pointer-events:auto}
@media(prefers-reduced-motion:reduce){#chat-window-view .bijou-drawer{transition:none!important}}

/* The small target sits inside the chat header, below the platform safe area. */
#chat-window-view .kiki-chat-header{touch-action:none;user-select:none;-webkit-user-select:none}
#chat-window-view .kiki-chat-header .bijou-header-drag{position:absolute;z-index:3;left:50%;bottom:0;transform:translateX(-50%);width:72px;height:18px;display:flex;align-items:flex-end;justify-content:center;padding:0 0 3px;box-sizing:border-box;user-select:none;-webkit-user-select:none;pointer-events:none;outline-offset:-2px}
#chat-window-view .bijou-header-drag>span{width:32px;height:3px;border-radius:3px;background:#f8b8d1;opacity:.48;transform:scaleX(1);transition:transform 140ms ease,opacity 140ms ease,box-shadow 140ms ease}
#chat-window-view .bijou-header-drag.bijou-pressed>span{transform:scaleX(1.25);opacity:.9;box-shadow:0 0 5px #ed85b7}
#chat-window-view .bijou-header-drag.bijou-threshold>span{transform:scale(1.15);opacity:1;box-shadow:0 0 7px #ffaad2}
#chat-window-view .bijou-header-drag:focus-visible{outline:1px solid #f8b8d1;border-radius:5px}
#chat-window-view .bijou-viewport{position:absolute;z-index:80;left:0;right:0;bottom:0;overflow:hidden;pointer-events:none}
#chat-window-view .bijou-viewport .bijou-drawer{top:0;height:100%;transform:translate3d(0,calc(-1 * var(--bijou-hidden,400px)),0);transition:transform 260ms cubic-bezier(.22,1,.36,1),opacity 140ms ease,visibility 0s linear 260ms;will-change:transform}
#chat-window-view .bijou-drawer.bijou-open{transform:translate3d(0,0,0);transition:transform 260ms cubic-bezier(.22,1,.36,1),opacity 140ms ease,visibility 0s}
#chat-window-view .bijou-drawer.bijou-peeking{visibility:visible;opacity:1;transition:transform 260ms cubic-bezier(.22,1,.36,1),opacity 140ms ease,visibility 0s}
#chat-window-view .bijou-drawer.bijou-tracking{transition:none}

:root { --pcc-chat-base-active: 1; }

/* ---------- 特殊消息：千禧 Y2K Discman 随身听红包（严格还原 Demo 配色、材质、LCD 与 CD Liner 详情页） ---------- */
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet {
  position: relative !important;
  width: 236px !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  padding: 11px 11px 10px !important;
  background: #171719 !important;
  background-color: #171719 !important;
  background-image: none !important;
  border: 1px solid rgba(255, 255, 255, .10) !important;
  border-radius: 28px !important;
  box-shadow: 0 14px 32px rgba(0, 0, 0, .42), inset 0 1px 0 rgba(255, 255, 255, .07) !important;
  color: #E5E7EB !important;
  overflow: hidden !important;
  display: block !important;
  cursor: pointer !important;
  transition: transform .18s ease, border-color .2s ease !important;
}
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet:active {
  transform: scale(.985);
}
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet::before,
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet::after {
  content: none !important;
  display: none !important;
}
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet.opened {
  background: #171719 !important;
  border-color: rgba(255, 255, 255, .07) !important;
  opacity: .92 !important;
}
/* 保留原生 .rp-bubble-content 节点供 App/壳子读取金额与祝福语，视觉交由 .pcc-discman 承担 */
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet.pcc-discman-ready > .rp-bubble-content {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

.pcc-discman {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  user-select: none;
  pointer-events: none;
}
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet .pcc-dm-top,
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet .pcc-dm-engraving,
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet .pcc-dm-power,
#chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) .message-red-packet .pcc-dm-power span {
  color: #9CA3AF !important;
}
.pcc-dm-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 7px;
  font-size: 7.5px;
  letter-spacing: .09em;
  color: #9CA3AF;
  line-height: 1.2;
}
.pcc-dm-power {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.pcc-dm-led {
  display: block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #E06389;
}
.pcc-discman.is-opened .pcc-dm-led {
  background: #6B7280;
}

/* 圆形托盘 + 黑银金属 CD + 烟熏亚克力上盖 */
.pcc-dm-well {
  position: relative;
  width: 162px;
  height: 162px;
  margin: 0 auto;
  border-radius: 50%;
}
.pcc-dm-tray {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: #212124;
  border: 2px solid #2C2C30;
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, .6);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.pcc-dm-laser {
  position: absolute;
  bottom: 16px;
  width: 24px;
  height: 34px;
  border-radius: 5px;
  background: #2C2C30;
  border: 1px solid rgba(255, 255, 255, .06);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  opacity: .6;
}
.pcc-dm-lens {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(30, 58, 138, .65);
  border: 1px solid rgba(96, 165, 250, .35);
}
.pcc-dm-rail {
  display: block;
  width: 12px;
  height: 2px;
  border-radius: 2px;
  background: #6B7280;
}
.pcc-dm-cd {
  position: relative;
  width: 138px;
  height: 138px;
  border-radius: 50%;
  box-shadow: 0 6px 14px rgba(0, 0, 0, .45);
  animation: pccDiscSpin 3.5s linear infinite;
}
.pcc-discman.is-opened .pcc-dm-cd,
.pcc-red-offscreen .pcc-dm-cd,
body.pcc-red-paused .pcc-dm-cd {
  animation-play-state: paused;
}
@keyframes pccDiscSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.pcc-dm-cd-sheen {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: conic-gradient(
    from 0deg,
    #232328 0deg,
    #484850 45deg,
    #232328 90deg,
    #60606A 135deg,
