  background-image: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%2730%27 height=%2730%27 viewBox=%270 0 30 30%27%3E%3Cg fill=%27%23211924%27 stroke=%27%23cfa0b0%27 stroke-width=%271%27 stroke-dasharray=%271.8 1.6%27%3E%3Ccircle cx=%278%27 cy=%2723%27 r=%274%27/%3E%3Ccircle cx=%2720%27 cy=%2712%27 r=%276.5%27/%3E%3C/g%3E%3C/svg%3E") !important;
}


/* ---------- 气泡入场动效 ---------- */
@media (prefers-reduced-motion: no-preference) {
  body.pcc-bubble-visible #chat-window-view #message-container .message-row.pcc-bubble-arriving:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich).assistant-row {
    animation: pccBubbleArriveLeft 0.36s cubic-bezier(.22, 1.12, .36, 1) both;
  }
  body.pcc-bubble-visible #chat-window-view #message-container .message-row.pcc-bubble-arriving:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich).user-row {
    animation: pccBubbleArriveRight 0.36s cubic-bezier(.22, 1.12, .36, 1) both;
  }
  body.pcc-bubble-visible #chat-window-view #message-container .message-row.pcc-bubble-arriving:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich).system-row {
    animation: pccBubbleArriveCenter 0.3s ease-out both;
  }
  @keyframes pccBubbleArriveLeft {
    0% { opacity: 0; transform: translate3d(-10px, 8px, 0) scale(.965); }
    100% { opacity: 1; transform: none; }
  }
  @keyframes pccBubbleArriveRight {
    0% { opacity: 0; transform: translate3d(10px, 8px, 0) scale(.965); }
    100% { opacity: 1; transform: none; }
  }
  @keyframes pccBubbleArriveCenter {
    0% { opacity: 0; transform: translateY(5px); }
    100% { opacity: 1; transform: none; }
  }
}
@media (prefers-reduced-motion: reduce) {
  body.pcc-bubble-visible #chat-window-view #message-container .message-row:not(.message-row--html-widget):not(.message-row--silly-mixed):not(.message-row--group-rich) {
    animation: none !important;
  }
}


:root { --pcc-bubble-base-active: 1; }
